body.script:
(function(){function animateCount(el,target,duration,isLocale){var startTime=null;el.textContent='0+';function step(ts){if(!startTime)startTime=ts;var p=Math.min((ts-startTime)/duration,1),cur=Math.floor((1-Math.pow(1-p,3))*target);el.textContent=(isLocale?cur.toLocaleString('id-ID'):cur)+'+';if(p<1)requestAnimationFrame(step);else el.textContent=(isLocale?target.toLocaleString('id-ID'):target)+'+';}requestAnimationFrame(step);}
function runCounters(){var eEl=document.getElementById("expNum");if(eEl)animateCount(eEl,new Date().getFullYear()-2012,1500,false);var cEl=document.getElementById("clientNum");if(cEl)animateCount(cEl,50000,2000,true);}
var observed=false,tgt=document.getElementById("expNum");
if(tgt&&'IntersectionObserver' in window){var obs=new IntersectionObserver(function(entries){entries.forEach(function(e){if(e.isIntersecting&&!observed){observed=true;runCounters();obs.disconnect();}});},{threshold:0.3});obs.observe(tgt);}
else{if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',runCounters);else setTimeout(runCounters,300);}
})();
